/* ============================================================
   TRIVIA OR NADA — game script, part 2 of 6 (speed pass).
   The game's single script now ships as six sequential files
   (assets/game-1.js ... assets/game-6.js) so the cover paints
   from the small index.html first and these files stream in
   behind it. The bootstrap in index.html loads them with
   async=false: they download in parallel and EXECUTE strictly
   in order, exactly as the one original script ran — statement
   order, pool contents, and every pool's internal order are
   unchanged (challenge links and Daily seeds depend on it).
   Part 1 holds every function declaration plus the hoisted
   variable bindings; parts 2-6 hold the executable statements
   (the question banks and the code woven through them) in
   their original order. Do not reorder parts or statements.
   ============================================================ */
"use strict";

"use strict";
/* ================= CHALLENGE DEALS & SEEDED RANDOM =================
   "Challenge a friend" (on the results screen) copies a link:
   the game's published address (see CHALLENGE_LINK_BASE) plus a
   challenge parameter and the pace. The original format carried
   a seed (?challenge=<seed>&pace=<pace>); the current format
   carries the game itself (v2 — see the end of this note).
   Opening that link deals a Gauntlet from a seeded random stream,
   so the deal is the exact same 20 questions — same order, same
   choices, same wager finales, same strict finale, same pace — on
   any device, in any fresh session. To make that true, EVERY
   random choice in this file goes through rand(): while a seed is
   installed it draws from a deterministic stream (mulberry32 over
   a hash of the seed); with no seed installed it is Math.random,
   exactly as the game always behaved. A page opened with a
   challenge seed installs it before anything else runs, so even
   the banks that are generated or repaired at load come out
   identical, and the challenge deal re-installs the seed so the
   deal always starts from the same point in the stream. That
   load-time determinism is itself fixed, not challenge-specific:
   every load — challenge or not — generates and repairs its
   banks under the same fixed LOAD_BANK_SEED (installed below),
   because generated questions bake their choices in at load; if
   those choices were dealt from Math.random on the challenger's
   load and from the challenge seed on the friend's, the same
   seed could never re-deal the same choices. The load seed is
   cleared once the banks exist (see the bottom of the script),
   so ordinary play after load is exactly as random as before.
   While a challenge deal is being built, the device-local
   seen-question memory is bypassed (dealBypassSeen): the friend's
   browser has seen different questions, and the deal must not
   depend on that.
   An ordinary Gauntlet is seeded too — starting one first
   generates its seed and installs it, and the seed is stored on
   the game itself (state.seed, and in the in-progress save), so
   the results screen's "Challenge a friend" button can put THAT
   seed in a link — but the ordinary deal itself is NOT built the
   challenge way: it consults this device's seen-question memory
   (the 25-game cooldown, see Seen-question memory) and takes its
   strict finale from the device alternation, exactly like every
   other mode. Only a deal built for a challenge link — the
   friend opening one — bypasses the memory and takes the strict
   finale from the stream, so that deal comes out byte-identical
   on every device that opens the link. (It also means a link
   re-deals the seeded game as the friend's device must see it —
   the challenger's own deal was filtered by the challenger's
   cooldown, which no link can carry.)
   The challenge game is a normal Gauntlet in every other respect —
   same scoring, judging, Pass / timeout rules, clocks, bonus and
   Legend rules — labelled as a challenge game on its questions,
   its results, and its saved score. There is no backend: the
   friend's score is saved only on their own device, so scores are
   compared by the players telling each other.
   CHALLENGE LINKS V2 (2026-11-10): a seed alone could not carry
   the challenger's game — their deal was filtered by their own
   seen-question cooldown and took its strict finale from their
   device's alternation, neither of which a seed can reproduce —
   so links minted from the results screen now carry the game
   itself: ?challenge=v2.… encodes each of the first 20 slots'
   pool and index, the Q10/Q15 strict bit, and the choice order
   actually shown for each multiple-choice question. Opening one
   reconstructs that exact game (see CHALLENGE LINKS V2 in the
   code below); it neither re-deals nor consults the seen store.
   The seeded links described above remain as the legacy format:
   links already shared in that form keep working exactly as
   they do here, and the Daily Gauntlet's seeded deal is
   unchanged. */
var _rngFn=null;
/* The game's canonical public address — triviaornada.com, the
   player-facing name for its website (W.'s call, 2026-11-10;
   the same hosted site also answers at savailleentertainment.com,
   but player-facing links carry triviaornada.com). Challenge
   links are minted against it rather than the address of
   whatever copy happens to be running: inside the Muse app,
   the page's own address is an internal gateway URL that cannot
   be shared. A challenge link minted anywhere — website, public
   link, or the phone app — therefore points at the one place a
   friend can always open. It is also the address the Share flow
   puts on every score (SHARE_SITE_URL). */
var CHALLENGE_LINK_BASE="https://triviaornada.com/";
var dealBypassSeen=false;
var challengeDeal=false;
var CHALLENGE=null;
try{
  var _chParams=new URLSearchParams(window.location.search);
  var _chSeed=_chParams.get("challenge");
  if(_chSeed){
    /* Two link formats share the "challenge" parameter: the v2
       payload ("v2.…"), which carries the challenger's actual
       game (see CHALLENGE LINKS V2 below), and the original seed
       format, kept working for links already shared. */
    if(_chSeed.indexOf("v2.")===0) CHALLENGE={v2:_chSeed.slice(3), pace:(_chParams.get("pace")==="relaxed" ? "relaxed" : "standard")};
    else CHALLENGE={seed:_chSeed, pace:(_chParams.get("pace")==="relaxed" ? "relaxed" : "standard")};
  }
}catch(e){ CHALLENGE=null; }
/* The fixed seed every load generates and repairs its question
   banks under (see CHALLENGE DEALS above): identical banks on
   every device and every load are what let a game seed re-deal
   a game byte-for-byte. It governs load-time generation only —
   the bottom of the script clears it before any game is dealt
   or resumed, and a challenge link's own seed is installed by
   startChallengeGame when its deal is built. */
var LOAD_BANK_SEED="trivia-or-nada-banks-v1";
installSeed(LOAD_BANK_SEED);
/* ================= PICTURE PACKS =================
   The 750 question pictures no longer ship as 750 separate files:
   the share review caps an artifact at 500 files and the loose
   pictures alone were 750 (751 files with this page). They now
   travel in 15 per-category ZIP packs under assets/ — faces in
   five packs, landmarks, paintings, flags and movie stills in one
   each, and the map outlines in six regional packs — so the whole
   game ships as 16 files. The question data is unchanged: every
   q.img still names its original "assets/..." path, and
   PIC_PACK_MAP below translates that path to [pack, entry] at
   display time. Packs use stored (uncompressed) entries, so the
   small unzipper here needs no library and no CDN: it reads the
   ZIP central directory and slices each entry's bytes straight
   into a Blob, shown through an object URL — the <img> element,
   its classes, and every credit line render exactly as before.
   Pictures were re-encoded smaller when the packs were built
   (photos at 420px wide, map PNGs as WebP, flags at 640px), which
   is why the packs total ~28 MB instead of ~92 MB of loose files.
   A pack is fetched once per session and kept in memory; where
   the Cache Storage API is available the download is also stored
   there (and plain HTTP caching applies regardless), so packs
   persist across games and sessions on the same device. If a pack
   fails to download or is corrupt, the question shows a clear
   "picture couldn't be loaded" note and plays on — the game never
   crashes on a picture. */
